parameters.inputSchema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Chat Response with Recommended Documents",
  "description": "Esquema para la respuesta del chat que incluye la respuesta del bot y una lista de documentos recomendados.",
  "type": "object",
  "required": [
    "respuesta",
    "documentosRecomendados"
  ],
  "properties": {
    "respuesta": {
      "type": "string",
      "description": "La respuesta textual generada por el bot."
    },
    "documentosRecomendados": {
      "type": "array",
      "description": "Una lista de documentos relevantes recomendados por la IA.",
      "items": {
        "type": "object",
        "required": [
          "title",
          "url",
          "type",
          "description"
        ],
        "properties": {
          "title": {
            "type": "string",
            "description": "El título del documento."
          },
          "url": {
            "type": ["string", "null"],
            "format": "uri",
            "description": "La URL para acceder al documento. Puede ser nula si no hay una URL directa."
          },
          "type": {
            "type": "string",
            "description": "El tipo de documento (ej. 'pdf', 'text', 'reglamento', 'instructivo')."
          },
          "description": {
            "type": "string",
            "description": "Una breve descripción del documento."
          }
        }
      },
      "default": []
    }
  },
  "additionalProperties": false
}
